def cohen_d(human,bot):
    human=np.asarray(human,dtype=float);bot=np.asarray(bot,dtype=float)
    if len(human)<2 or len(bot)<2: raise ValueError('Need two matches per group')
    pooled=((len(human)-1)*human.var(ddof=1)+(len(bot)-1)*bot.var(ddof=1))/(len(human)+len(bot)-2)
    delta=bot.mean()-human.mean()
    if pooled==0:
        if delta==0: return 0.0
        raise ValueError('Unequal constants have undefined standardised difference')
    return float(delta/np.sqrt(pooled))

import math

def rms(effects):
