def auc(human_scores,bot_scores):
    if not human_scores or not bot_scores: raise ValueError('Need both classes')
    credit=0.0
    for b in bot_scores:
        for h in human_scores:
            credit+=(b>h)+0.5*(b==h)
    return credit/(len(human_scores)*len(bot_scores))

